export function getCatalogItemsByCategory(categoryId: string): CatalogItem[] {
  return CATALOG_ITEMS.filter((item) => item.categoryId === categoryId);
}

export function getCatalogItemsBySubcategory(subcategoryId: string): CatalogItem[] {
  return CATALOG_ITEMS.filter((item) => item.subcategoryId === subcategoryId);
}

export function getCatalogItemById(id: string): CatalogItem | undefined {
  return CATALOG_ITEMS.find((item) => item.id === id);
}
